node --input-type=module -e '
import assert from "node:assert/strict";
import { retrySchedule } from "./src/retry-schedule.js";

// retries: 0 -> []
assert.deepEqual(retrySchedule({ retries: 0, baseMs: 100, factor: 2, maxMs: 1000, jitter: "none" }), []);

// full jitter
assert.deepEqual(
  retrySchedule({ retries: 2, baseMs: 100, factor: 2, maxMs: 1000, jitter: "full" }, () => 0.5),
  [50, 100]
);
// equal jitter
assert.deepEqual(
  retrySchedule({ retries: 2, baseMs: 100, factor: 2, maxMs: 1000, jitter: "equal" }, () => 0.5),
  [75, 150]
);

// rand called once per entry, in order; not at all with none
const calls = [];
const rand = (v) => { calls.push(v); return 0; };
retrySchedule({ retries: 3, baseMs: 10, factor: 1, maxMs: 10, jitter: "full" }, () => 0);
assert.deepEqual(calls, []);
retrySchedule({ retries: 2, baseMs: 10, factor: 2, maxMs: 100, jitter: "full" }, (i) => 0);
const seen = [];
retrySchedule({ retries: 3, baseMs: 10, factor: 2, maxMs: 100, jitter: "full" }, () => { seen.push(seen.length); return 0; });
assert.deepEqual(seen, [0, 1, 2]);

// rounding: rounds to 0 -> 1
assert.deepEqual(retrySchedule({ retries: 1, baseMs: 0.4, factor: 1, maxMs: 1, jitter: "none" }), [1]);
// factor: 1
assert.deepEqual(retrySchedule({ retries: 3, baseMs: 7, factor: 1, maxMs: 100, jitter: "none" }), [7, 7, 7]);

// TypeErrors
const ty = (fn) => assert.throws(fn, TypeError);
ty(() => retrySchedule());
ty(() => retrySchedule(null));
ty(() => retrySchedule("x"));
ty(() => retrySchedule(42));
ty(() => retrySchedule({ retries: 4, baseMs: 100, factor: 2, maxMs: 1000 }));                       // missing jitter
ty(() => retrySchedule({ baseMs: 100, factor: 2, maxMs: 1000, jitter: "none" }));                     // missing retries
ty(() => retrySchedule({ retries: 4.5, baseMs: 100, factor: 2, maxMs: 1000, jitter: "none" }));       // non-integer
ty(() => retrySchedule({ retries: -1, baseMs: 100, factor: 2, maxMs: 1000, jitter: "none" }));
ty(() => retrySchedule({ retries: 101, baseMs: 100, factor: 2, maxMs: 1000, jitter: "none" }));
ty(() => retrySchedule({ retries: 0, baseMs: 0, factor: 2, maxMs: 1000, jitter: "none" }));           // baseMs not > 0
ty(() => retrySchedule({ retries: 0, baseMs: Infinity, factor: 2, maxMs: 1000, jitter: "none" }));
ty(() => retrySchedule({ retries: 0, baseMs: "100", factor: 2, maxMs: 1000, jitter: "none" }));
ty(() => retrySchedule({ retries: 0, baseMs: 100, factor: 0.5, maxMs: 1000, jitter: "none" }));       // factor < 1
ty(() => retrySchedule({ retries: 0, baseMs: 100, factor: NaN, maxMs: 1000, jitter: "none" }));
ty(() => retrySchedule({ retries: 0, baseMs: 100, factor: 2, maxMs: -5, jitter: "none" }));
ty(() => retrySchedule({ retries: 0, baseMs: 100, factor: 2, maxMs: 1000, jitter: "deciso" }));
ty(() => retrySchedule({ retries: 1, baseMs: 100, factor: 2, maxMs: 1000, jitter: "full" }));         // rand missing
ty(() => retrySchedule({ retries: 1, baseMs: 100, factor: 2, maxMs: 1000, jitter: "equal" }, 42));

// RangeError baseMs > maxMs
assert.throws(() => retrySchedule({ retries: 1, baseMs: 200, factor: 2, maxMs: 100, jitter: "none" }), RangeError);
// TypeError priority over RangeError: bad retries AND baseMs > maxMs
assert.throws(() => retrySchedule({ retries: "x", baseMs: 200, factor: 2, maxMs: 100, jitter: "none" }), TypeError);
// rand TypeError checked with R1: rand missing AND baseMs > maxMs
assert.throws(() => retrySchedule({ retries: 1, baseMs: 200, factor: 2, maxMs: 100, jitter: "full" }), TypeError);

// rand invalid returns -> RangeError
for (const bad of [1, -0.1, NaN, Infinity, "0.5", undefined, null, true]) {
  assert.throws(
    () => retrySchedule({ retries: 1, baseMs: 100, factor: 2, maxMs: 1000, jitter: "full" }, () => bad),
    RangeError, `rand returning ${String(bad)}`
  );
}

// options never mutated
const opts = Object.freeze({ retries: 2, baseMs: 100, factor: 2, maxMs: 1000, jitter: "none" });
assert.deepEqual(retrySchedule(opts, () => 0.5), [100, 200]);

console.log("all sanity checks passed");
'
